import{_ as a,o as t,c as o,a4 as r}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"05 · Data Flow & the Muhurta Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"reference/05-data-flow-and-muhurta.md","filePath":"reference/05-data-flow-and-muhurta.md","lastUpdated":1788414836000}'),i={name:"reference/05-data-flow-and-muhurta.md"};function n(s,e,d,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="_05-·-data-flow-the-muhurta-pipeline" tabindex="-1">05 · Data Flow &amp; the Muhurta Pipeline <a class="header-anchor" href="#_05-·-data-flow-the-muhurta-pipeline" aria-label="Permalink to &quot;05 · Data Flow &amp; the Muhurta Pipeline&quot;">​</a></h1><p>How a request becomes an answer, end-to-end — then a deep look at the muhurta scorer (split across three files in <code>personal/</code>), the most intricate consumer.</p><hr><h2 id="end-to-end-data-flow" tabindex="-1">End-to-end data flow <a class="header-anchor" href="#end-to-end-data-flow" aria-label="Permalink to &quot;End-to-end data flow&quot;">​</a></h2><pre class="mermaid">flowchart TB
    REQ[&quot;Request: date(s), city, system, [birth data], [activity]&quot;]
    LOC[&quot;location resolver&lt;br/&gt;(CITIES → Nominatim)&quot;]
    ENGINE[&quot;Engine.calculate() / calculate_bulk()&lt;br/&gt;Drik · SS · Vakya&quot;]
    DAY[&quot;PanchangamDay&lt;br/&gt;(one per day)&quot;]

    REQ --&gt; LOC --&gt; ENGINE --&gt; DAY

    DAY --&gt; MUH[&quot;muhurta.day_slots()&lt;br/&gt;scored, tiered slots&quot;]
    DAY --&gt; TARA[&quot;tarabalam / chandrabalam&lt;br/&gt;find_tarabalam_days&quot;]
    DAY --&gt; GOCH[&quot;gochara rules + phalalu&lt;br/&gt;verdicts &amp; daily reading&quot;]
    DAY --&gt; SHUD[&quot;panchanga_shuddhi&lt;br/&gt;five-limb verdict&quot;]
    DAY --&gt; ICS[&quot;ICSGenerator&lt;br/&gt;.ics feeds&quot;]

    EPH[&quot;raw ephemeris&lt;br/&gt;(swisseph)&quot;] --&gt; CAL[&quot;combustion / graha_yuddha /&lt;br/&gt;ingress / eclipse calendars&quot;]

    MUH --&gt; MCP[&quot;MCP tools (JSON)&quot;]
    TARA --&gt; MCP
    GOCH --&gt; MCP
    SHUD --&gt; MCP
    CAL --&gt; MCP
    ICS --&gt; PAGES[&quot;GitHub Pages (webcal)&quot;]
    MCP --&gt; CLIENT[&quot;Claude / Cursor / any MCP client&quot;]
    DAY --&gt; SITE[&quot;Vite website + TypeScript scorer&quot;]
</pre><p>Two notes:</p><ul><li>The five <strong>calendar</strong> features (combustion, graha yuddha, ingress, eclipse) go largely straight to ephemeris, not through <code>PanchangamDay</code>.</li><li>The landing page implements the scorer in TypeScript for in-browser use. Python owns the activity catalogue; a generated JSON contract and parity tests prevent the two surfaces from silently diverging.</li></ul><hr><h2 id="the-muhurta-scorer-in-depth" tabindex="-1">The muhurta scorer in depth <a class="header-anchor" href="#the-muhurta-scorer-in-depth" aria-label="Permalink to &quot;The muhurta scorer in depth&quot;">​</a></h2><p><strong>Goal:</strong> given a day (or range), an activity, and optional birth data, return a ranked list of auspicious time slots — each with a transparent reason list and a tier (Excellent / Good / Fair / Avoid).</p><h3 id="three-file-layout" tabindex="-1">Three-file layout <a class="header-anchor" href="#three-file-layout" aria-label="Permalink to &quot;Three-file layout&quot;">​</a></h3><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>personal/activity_rules.py</code></td><td>Declarative <code>ACTIVITY_RULES</code> dict — 35 canonical activity profiles, pure data.</td></tr><tr><td><code>personal/activity_catalog.py</code></td><td>Ordered browser-supported subset and selector groups.</td></tr><tr><td><code>personal/slot_scorers.py</code></td><td>Atomic scoring functions + <code>_DayContext</code> dataclass.</td></tr><tr><td><code>personal/muhurta.py</code></td><td>Orchestrator (~530 lines) — public API only.</td></tr></tbody></table><h3 id="configuration-activity-rules-activity-rules-py" tabindex="-1">Configuration: <code>ACTIVITY_RULES</code> (<code>activity_rules.py</code>) <a class="header-anchor" href="#configuration-activity-rules-activity-rules-py" aria-label="Permalink to &quot;Configuration: \`ACTIVITY_RULES\` (\`activity_rules.py\`)&quot;">​</a></h3><p>A declarative dict — <strong>adding an activity is primarily a data change</strong>, plus a catalogue/export update and source evidence. Entries carry hard gates, preferences, exact admitted Tithis/Nakshatras/Lagnas, manual practitioner checks, and (where verified) a stable provenance claim. Source-facing Nakshatra spellings are preserved in this declarative contract, but Python and TypeScript normalize <code>Ashwini</code>→<code>Ashvini</code> and <code>Moola</code>→<code>Mula</code> before membership tests. These are the only non-canonical names currently present; parity tests require both scorers to apply the same aliases. Python/MCP support 35 canonical activity profiles and one legacy alias (<code>litigation</code> → <code>court</code>), for 36 accepted API keys. The browser-supported subset is 30 activities in seven selector groups, declared in <code>activity_catalog.py</code>. The backend-only canonical profiles are <code>beginning</code>, <code>construction_roof</code>, <code>coronation</code>, <code>cremation</code>, and <code>wood_cutting</code>. <code>tools/export_activity_rules.py</code> generates the exact rule fields consumed by TypeScript. <code>npm run activity:check</code> and the Python contract tests fail if the committed export or static selector drifts. Tithi-family scoring is likewise shared as a behavioral contract: the browser exports <code>avoid_tithi_class</code> and its pure scorer mirrors Python&#39;s preferred and avoided families, Amavasya precedence, and Pushya/Siddhi Rikta neutralization.</p><h3 id="the-pipeline" tabindex="-1">The pipeline <a class="header-anchor" href="#the-pipeline" aria-label="Permalink to &quot;The pipeline&quot;">​</a></h3><pre class="mermaid">flowchart TB
    A[&quot;day + activity + birth data&quot;] --&gt; B{&quot;Day-level HARD filters&quot;}
    B --&gt;|&quot;eclipse · Disha Shoola · Panchaka ·&lt;br/&gt;Khar/Adhika/Pitru · Simha-stha ·&lt;br/&gt;combust · skip-on-yoga&quot;| X[&quot;return [] (dropped_days + reason)&quot;]
    B --&gt;|&quot;passes&quot;| C[&quot;15 named day or night Muhurtas&quot;]
    C --&gt; D{&quot;Overlaps a hard-avoid window?&quot;}
    D --&gt;|&quot;yes&quot;| X2[&quot;exclude the whole indivisible Muhurta&quot;]
    D --&gt;|&quot;no&quot;| F[&quot;Score intrinsic nature + dominant Choghadiya&lt;br/&gt;and personal/activity factors&quot;]
    F --&gt; G[&quot;Tier (absolute + relative bands)&quot;]
    G --&gt; H[&quot;Dosha tier-cap: personal/day dosha ⇒ max Good&quot;]
    H --&gt; I[&quot;Sort base candidates&quot;]
    I --&gt; J{&quot;Drik activity has&lt;br/&gt;deterministic chart rules?&quot;}
    J --&gt;|&quot;yes&quot;| K[&quot;Resolve canonical local Lagna&lt;br/&gt;and recompute Whole Sign houses&quot;]
    K --&gt; K2[&quot;Screen every sampled state&lt;br/&gt;edges + cadence + interior transitions&quot;]
    J --&gt;|&quot;no candidates, unsupported or unavailable&quot;| L[&quot;Keep base shortlist&lt;br/&gt;show exact disclosure state&quot;]
    K2 --&gt; M[&quot;Refill survivors and return top 10&quot;]
    L --&gt; M
</pre><h3 id="browser-election-chart-post-screen" tabindex="-1">Browser election-chart post-screen <a class="header-anchor" href="#browser-election-chart-post-screen" aria-label="Permalink to &quot;Browser election-chart post-screen&quot;">​</a></h3><p>For Drik searches, 12 source-backed activity profiles have an additional browser-only post-ranking screen. The browser sends only candidate city coordinates/timezone and candidate UTC instants to the Astro guest gateway; profile identity, birth data, activity and selected role do not leave the browser. The authenticated DashaFlow sidecar returns Lahiri candidate-time planetary positions. For every sample, the browser resolves the validated selected-city Lagna from its local Drik/Lahiri transition map and recomputes all nine Whole Sign houses from planetary Rashi relative to that Lagna before applying the generated deterministic rule table. Returned sidecar house numbers cannot override this frame. Every computed outcome retains its claim-specific source locator.</p><p>The browser samples each half-open window at its start, final represented minute and 10-minute cadence, then at the minute before, at, and after every known interior Drik/Lahiri Lagna transition. It dynamically packs no more than 24 unique instants into each request and makes at most five requests per search. If the selected city/date lacks the precomputed Lagna boundary support, the chart screen is <code>unavailable</code>; it does not claim endpoint-only whole-window assurance.</p><p>External boundary checks found minute-level Drik Panchang/DashaFlow Lagna differences. A window that only partly overlaps the five-minute guard around a local transition is therefore retained below Excellent with Lagna-dependent general, Travel and Gruhapravesha rules marked <code>unknown</code>. A window spanning the complete guard evaluates both canonical local Lagna states. Moon/Nakshatra-only personal rules for Seemantha and Surgery remain computable.</p><p>A failed <code>reject</code> predicate removes a window. A passed <code>prefer</code> predicate is a tie-break only and never changes the raw heuristic score. A supported unresolved boundary outcome is retained as <code>unknown</code>, requires review, and caps an otherwise Excellent result to Good. A malformed or incomplete network response instead rejects the whole batch and preserves the base shortlist with an explicit <code>unavailable</code> state. Activities without a deterministic chart predicate, including Gold / jewelry purchase, make no chart request. An empty base shortlist is <code>not-run</code> and likewise makes no chart request. Surya Siddhanta and Vakya searches likewise remain separate rather than silently receiving a Drik/Lahiri chart.</p><p>Travel, Gruhapravesha, Seemantha and Surgery also identify a primary traveller, householder, mother or patient respectively. Existing generic group scoring is preserved. The additional source-specific natal rule is evaluated locally from the exact returned Chandra facts and canonical local Lagna for every sampled state; an exact prohibition can reject a window and an exact preference is only a tie-break. Stable saved-profile role IDs can persist as a versioned browser-local preference, while one-off participants remain session-only. Names, role IDs and profile IDs are never sent, shared or exported.</p><p>Personal removals are applied first and chart removals second, so their counts are mutually exclusive. The result&#39;s remaining manual rows come from the generated structured activity-check contract: all 30 browser activities map their deterministic Panchangam fields, personal/chart rule IDs and each manual row&#39;s display section explicitly, without regex-based prose classification.</p><p>See <a href="./54-muhurtam-election-chart-screening">Muhurtam election-chart screening</a> for the complete 23-rule matrix, sampled-state semantics, personal-role formulas, privacy contract, source locators and manual remainder.</p><h3 id="what-evaluate-slot-adds-up-slot-scorers-py-muhurta-py" tabindex="-1">What <code>_evaluate_slot()</code> adds up (<code>slot_scorers.py</code> + <code>muhurta.py</code>) <a class="header-anchor" href="#what-evaluate-slot-adds-up-slot-scorers-py-muhurta-py" aria-label="Permalink to &quot;What \`_evaluate_slot()\` adds up (\`slot_scorers.py\` + \`muhurta.py\`)&quot;">​</a></h3><p>Per slot, the score combines named-Muhurta nature (<code>Abhijit</code>/<code>Brahma</code> +2, other auspicious +1, inauspicious -2) with the dominant Choghadiya (<code>Amrit</code> +3, <code>Shubh</code>/<code>Labh</code> +2, <code>Char</code> +1; others 0), in five reason groups:</p><ul><li><strong>slot_quality</strong> — named Muhurta identity, deity and intrinsic nature; dominant Choghadiya (with boundary straddles disclosed); +2 for Amrita Kalam overlap.</li><li><strong>day_quality</strong> — special yogas (Sarvartha/Amrita +2, <strong>Siddha Yoga +1</strong>, Dvi/Tripushkara +1, Visha/Dagdha −2, Vyatipata/Vaidhriti −2); tithi class (Rikta −2 with classical neutralization; preferred +1); Nitya-yoga disposition (hard-avoid −2, partial-avoid −1 within its dosha window, auspicious +1); Anandadi ±1; Simha-stha Shukra −2 (wedding).</li><li><strong>group_fit</strong> (per person, ±1 each) — <strong>Tarabalam</strong> (auspicious taras 2/4/6/8/9 +1, unfav 1/3/5/7 −1); <strong>Chandrabalam</strong> (good 1/3/6/7/10/11 +1, avoid 4/8/12 −1, puja-remedial 2/5/9 flagged); <strong>Lagna position</strong> vs janma rasi (and janma lagna if given) — kendra/trikona +1, ashtama −1.</li><li><strong>activity_match</strong> — tithi-class preferred +1; <strong>tithi-class avoided −1</strong> (e.g. Jaya for union ceremonies, Purna for legal contests); vara match; <strong>hora-ruler vara</strong> match (+1); Bhadra-Puchha &amp; Nakshatra-Mukha bonuses; activity-class lagna (Sthira for wedding, Chara for travel…); Choghadiya preference; <strong>Panchaka Rahita</strong> recomputed at the slot&#39;s rising lagna (Mrityu −3 universal, other doshas −2 if the activity matches <code>avoid_for</code>).</li><li><strong>notes</strong> — doctrinal caveats (e.g. &quot;Siddhi rectifies tara but not chandra&quot;).</li></ul><h4 id="rikta-neutralization-score-tithi-class" tabindex="-1">Rikta neutralization (<code>score_tithi_class</code>) <a class="header-anchor" href="#rikta-neutralization-score-tithi-class" aria-label="Permalink to &quot;Rikta neutralization (\`score_tithi_class\`)&quot;">​</a></h4><p>When the day&#39;s tithi is Rikta (4/9/14), two classical conditions reduce the −2 penalty:</p><table tabindex="0"><thead><tr><th>Condition</th><th>Effect</th><th>Source</th></tr></thead><tbody><tr><td>Nakshatra = Pushya</td><td>Rikta cancelled (0)</td><td>Muhurta Chintamani</td></tr><tr><td>Sarvartha or Amrita Siddhi Yoga active</td><td>Partially offset (−1)</td><td>B.V. Raman Muhurtha</td></tr></tbody></table><p>Both conditions emit an explicit reason note. When both apply, Pushya takes precedence (full cancellation).</p><h3 id="tiering-the-dosha-cap-muhurta-py" tabindex="-1">Tiering &amp; the dosha cap (<code>muhurta.py</code>) <a class="header-anchor" href="#tiering-the-dosha-cap-muhurta-py" aria-label="Permalink to &quot;Tiering &amp; the dosha cap (\`muhurta.py\`)&quot;">​</a></h3><p>Two band schemes: <strong>absolute</strong> (≥7 Excellent / ≥4 Good / ≥1 Fair / ≤0 Avoid) and <strong>relative</strong> (75/50/25 percentiles of the found range). Crucially, a slot with an unresolved <strong>personal dosha</strong> (<code>ashtama_chandra</code>, <code>chandra_avoid</code>, <code>ashtama_lagna</code>, <code>chandra_remedial</code>, <code>tara_dosha</code>) or <strong>day dosha</strong> (<code>rikta_tithi</code>, <code>amavasya</code>, <code>visha_dagdha_yoga</code>, <code>vyatipata_vaidhriti</code>) is <strong>capped at Good</strong> even if it scored Excellent — classical doctrine: yogas don&#39;t fully rectify doshas.</p><h3 id="slot-time-precision" tabindex="-1">Slot-time precision <a class="header-anchor" href="#slot-time-precision" aria-label="Permalink to &quot;Slot-time precision&quot;">​</a></h3><p>If an <code>engine</code> is passed, the scorer recomputes Moon-driven facts at each slot&#39;s <em>start</em> via <code>engine.facts_at(slot_start)</code>, so a late-afternoon slot is judged against the nakshatra/tithi/yoga active <em>then</em>, not at sunrise. Without an engine it falls back to the day&#39;s sunrise snapshot.</p><h3 id="diagnose-day-muhurta-py" tabindex="-1"><code>diagnose_day()</code> (<code>muhurta.py</code>) <a class="header-anchor" href="#diagnose-day-muhurta-py" aria-label="Permalink to &quot;\`diagnose_day()\` (\`muhurta.py\`)&quot;">​</a></h3><p>A lightweight pre-check that returns <em>why</em> a day was dropped (eclipse, Disha Shoola, skip-yoga, Panchaka, Khar-Maasa…) — this populates <code>find_muhurta</code>&#39;s <code>dropped_days[]</code>. Internally calls <code>_day_skip_reason()</code>, the same helper used by <code>day_slots()</code> to keep day-skip logic in one place.</p><hr><h2 id="the-supporting-personal-modules" tabindex="-1">The supporting personal modules <a class="header-anchor" href="#the-supporting-personal-modules" aria-label="Permalink to &quot;The supporting personal modules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Function</th><th>Output</th></tr></thead><tbody><tr><td><code>activity_rules.py</code></td><td><code>ACTIVITY_RULES</code>, <code>ACTIVITIES</code></td><td>35 canonical profiles and one accepted compatibility alias</td></tr><tr><td><code>activity_catalog.py</code></td><td><code>BROWSER_ACTIVITY_GROUPS</code>, <code>BROWSER_ACTIVITIES</code></td><td>Explicit browser capability boundary and selector ordering</td></tr><tr><td><code>slot_scorers.py</code></td><td><code>score_tithi_class</code>, <code>score_tara</code>, <code>score_chandra</code>, <code>score_lagna</code>, <code>score_special_yogas</code>, <code>score_nitya_yoga</code>, <code>anandadi_day_modifier</code>, <code>_DayContext</code></td><td>All atomic scoring functions; <code>_DayContext</code> bundles day-constant params</td></tr><tr><td><code>tarabalam.py</code></td><td><code>tara_number</code>, <code>is_auspicious_tara</code>, <code>good_for_all</code></td><td>9-tara strength from a birth star</td></tr><tr><td><code>chandrabalam.py</code></td><td><code>chandra_position</code>, <code>chandra_verdict</code>, <code>rasi_from_nakshatra</code></td><td>12-position Moon-sign strength</td></tr><tr><td><code>lagna_position.py</code></td><td><code>lagna_position</code>, <code>lagna_verdict</code>, <code>lagna_class_of</code></td><td>kendra/trikona/ashtama + Chara/Sthira/Dvisvabhava class</td></tr><tr><td><code>lagna_hora.py</code></td><td><code>get_horas</code>, <code>get_lagna_transitions</code></td><td>24 planetary hours; ascendant boundaries (swisseph, ±0.5 min)</td></tr><tr><td><code>nitya_yoga.py</code></td><td><code>nitya_disposition</code></td><td>hard-avoid / partial-avoid / auspicious / neutral</td></tr><tr><td><code>tithi_class.py</code></td><td><code>tithi_family</code>, <code>is_rikta</code></td><td>Nanda/Bhadra/Jaya/Rikta/Purna</td></tr><tr><td><code>phalalu.py</code></td><td><code>rasi_phalalu</code></td><td>deterministic daily reading (every line traced to a computation)</td></tr></tbody></table><blockquote><p><strong>Design throughline:</strong> every score and every deterministic <code>phalalu.py</code> line is reproducible and explainable. Separately generated website prose is checked against computed transit facts but remains heuristic interpretation. Project ranking heuristics are labelled as heuristics; textual doctrine requires a ledger citation. Per-person components are independent contributors, so people can be added or removed without hidden model state.</p></blockquote>`,41)])])}const g=a(i,[["render",n]]);export{p as __pageData,g as default};
